(function(){
'use strict';

function normalizeCards(){
  const list=document.getElementById('team-builder-list');
  if(!list) return;

  list.querySelectorAll('[data-tb-add]').forEach(row=>{
    /* Find the identity container and badges generated by previous versions. */
    let identity=row.querySelector('.team-builder-option-identity');
    let badges=row.querySelector('.tb-option-types,.team-builder-option-types');

    if(!identity) return;

    let content=identity.parentElement;
    if(!content || content===row || !content.classList.contains('team-builder-option-content')){
      const wrap=document.createElement('span');
      wrap.className='team-builder-option-content';

      identity.before(wrap);
      wrap.appendChild(identity);

      if(badges && badges.parentElement===row){
        wrap.appendChild(badges);
      }else if(badges && badges.parentElement!==wrap){
        wrap.appendChild(badges);
      }

      content=wrap;
    }else if(badges && badges.parentElement!==content){
      content.appendChild(badges);
    }
  });
}

function run(){
  normalizeCards();

  const list=document.getElementById('team-builder-list');
  if(list && window.MutationObserver){
    let pending=false;
    new MutationObserver(()=>{
      if(pending) return;
      pending=true;
      requestAnimationFrame(()=>{
        pending=false;
        normalizeCards();
      });
    }).observe(list,{childList:true,subtree:true});
  }
}

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',run,{once:true});
}else{
  run();
}
})();
